commit;

-- Comprobación final ------------------------------------------------------------------------------------------------
select
  (select count(*) from public.competencias)                                                                         as competencias,
  (select count(*) from public.competencias where slug in ('redes-moviles', 'estaciones-base', 'planificacion-rf', 'optimizacion-rf', 'atoll', 'drive-test', 'fibra-optica', 'ftth-ftx', 'empalme-de-fibra', 'otdr', 'radioenlaces', 'cctv', 'seguridad-electronica', 'deteccion-incendios', 'enrutamiento', 'ospf', 'bgp', 'mpls', 'cisco', 'ccna', 'ccnp', 'ccie', 'cableado-estructurado', 'plc', 'tia-portal', 'studio-5000', 'scada', 'hmi', 'dcs', 'instrumentacion-control', 'variadores-frecuencia', 'redes-industriales', 'modbus', 'profibus', 'diseno-pcb', 'altium', 'proteus', 'kicad', 'microcontroladores', 'sistemas-embebidos', 'arduino', 'raspberry-pi', 'esp32', 'matlab', 'simulink', 'etap', 'digsilent', 'dialux', 'estudios-electricos', 'flujo-de-carga', 'cortocircuito', 'coordinacion-protecciones', 'arc-flash', 'sistemas-de-potencia', 'subestaciones', 'instalaciones-electricas', 'media-tension', 'baja-tension', 'tableros-electricos', 'puesta-a-tierra', 'cne', 'iec-60909', 'ieee-1584', 'nfpa-70e'))                                                  as del_lote_3_presentes,
  (select count(*) from public.competencias where categoria is null)                                                  as sin_categoria_debe_ser_0,
  (select count(*) from public.competencias where deteccion = 'revisar')                                              as en_revision,
  (select string_agg(area || '=' || n, ', ' order by area) from (select area, count(*) n from public.competencias group by area) x) as por_area,
  (select count(*) from (select lower(t) from public.competencias c, unnest(array[c.nombre] || c.variantes) as t
                          where c.estado = 'activa' group by lower(t) having count(distinct c.slug) > 1) x)           as terminos_repetidos_debe_ser_0,
  has_table_privilege('anon', 'public.competencias', 'select')                                                        as anon_lee,
  has_table_privilege('anon', 'public.competencias', 'insert') or has_table_privilege('authenticated', 'public.competencias', 'update') as alguien_escribe_debe_ser_false;
